<script>
    document.addEventListener('DOMContentLoaded', () => {
  const imgOrigin = document.getElementById('img-origin');
  const imgContrast = document.getElementById('img-contrast');

  if (!imgOrigin || !imgContrast) {
    console.warn('Imgs não encontradas: verifique #img-origin e #img-contrast');
    return;
  }

 
  function updateByBodyClass() {
    const isContrast = document.body.classList.contains('contrast');

    if (isContrast) {
      imgContrast.style.display = 'block';
      imgOrigin.style.display = 'none';
    } else {
      imgContrast.style.display = 'none';
      imgOrigin.style.display = 'block';
    }
  }


  function updateInitial() {
    if (document.body.classList.contains('contrast')) {
      updateByBodyClass();
      return;
    }

    const contrastLS = localStorage.getItem('contrast');
    if (contrastLS === 'enable') {
      
      document.body.classList.add('contrast');
      updateByBodyClass();
    } else if (contrastLS === 'disable') {
      document.body.classList.remove('contrast');
      updateByBodyClass();
    } else {
      // padrão: sem contraste
      updateByBodyClass();
    }
  }

 
  const observer = new MutationObserver((mutations) => {
    for (const m of mutations) {
      if (m.type === 'attributes' && m.attributeName === 'class') {
        updateByBodyClass();
        break;
      }
    }
  });
  observer.observe(document.body, { attributes: true, attributeFilter: ['class'] });

  // Escuta alterações vindas de outra aba via storage
  window.addEventListener('storage', (e) => {
    if (e.key === 'contrast') {
      // se outra aba mudou o localStorage, sincroniza o body e a visualização
      if (e.newValue === 'enable') {
        document.body.classList.add('contrast');
      } else {
        document.body.classList.remove('contrast');
      }
      updateByBodyClass();
    }
  });

  // Inicializa
  updateInitial();

  // Opcional: função pública pra alternar (se quiser ligar/desligar via botão sem reload)
  window.toggleContrast = function toggleContrast() {
    const isNow = !document.body.classList.contains('contrast');
    if (isNow) {
      document.body.classList.add('contrast');
      localStorage.setItem('contrast', 'enable');
    } else {
      document.body.classList.remove('contrast');
      localStorage.setItem('contrast', 'disable');
    }
    updateByBodyClass();
  };
});

</script>


